# Lunar Konstruksi - Fase 7.5 FIELD ARCHIVE Total Redesign
Set-StrictMode -Version Latest
$ErrorActionPreference="Stop"

function P([string]$m){Write-Host "[FASE 7.5] $m" -ForegroundColor Cyan}
function F([string]$m){Write-Host "";Write-Host "[FASE 7.5] GAGAL: $m" -ForegroundColor Red;exit 1}
function W([string]$p,[string]$c){$d=Split-Path -Parent $p;if($d -and -not (Test-Path -LiteralPath $d)){New-Item -ItemType Directory -Force -Path $d|Out-Null};$e=New-Object System.Text.UTF8Encoding($false);[IO.File]::WriteAllText($p,$c,$e)}
function D([string]$v){[Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($v))}

$root=(& git rev-parse --show-toplevel 2>$null);if(-not $root){F "Jalankan script dari repository Lunar Konstruksi."};$root=$root.Trim();Set-Location $root
$branch=(& git branch --show-current).Trim();$head=(& git rev-parse --short HEAD).Trim();P "Repo   : $root";P "Branch : $branch";P "HEAD   : $head"
$tracked=& git status --porcelain --untracked-files=no;if($tracked){Write-Host "[FASE 7.5] Ada tracked changes. Installer akan backup file frontend yang ditimpa." -ForegroundColor Yellow;Write-Host $tracked}
$req=@(
  "package.json",
  "features/public-site/server.ts",
  "features/public-site/public-site.types.ts",
  "features/navigation/server.ts",
  "features/site-settings/server.ts",
  "components/site/home-page.tsx",
  "components/site/about-page.tsx",
  "components/site/services-page.tsx",
  "components/site/projects-page.tsx",
  "components/site/contact-page.tsx",
  "components/site/site-header.tsx",
  "components/site/site-footer.tsx",
  "components/site/redesign/public-contact-form.tsx",
  "app/api/public/leads/route.ts"
);$miss=@($req|Where-Object{-not(Test-Path -LiteralPath $_)});if($miss.Count){$miss|ForEach-Object{Write-Host " - $_"};F "Fondasi Fase 1-7 belum lengkap."}

$stamp=Get-Date -Format "yyyyMMdd-HHmmss";$backupDir=Join-Path $root ".lunar-backups/phase7_5-$stamp";New-Item -ItemType Directory -Force -Path $backupDir|Out-Null
$backupFiles=@(
  "components/site/home-page.tsx",
  "components/site/about-page.tsx",
  "components/site/services-page.tsx",
  "components/site/projects-page.tsx",
  "components/site/contact-page.tsx",
  "components/site/site-header.tsx",
  "components/site/site-footer.tsx",
  "components/site/redesign/public-contact-form.tsx"
);foreach($file in $backupFiles){$src=Join-Path $root $file;if(Test-Path -LiteralPath $src){$dest=Join-Path $backupDir ($file.Replace("/","__"));Copy-Item -LiteralPath $src -Destination $dest -Force}};Write-Host "[FASE 7.5] Backup: $backupDir" -ForegroundColor DarkGray

$payload=@{}
$payload["PHASE7_5_FIELD_ARCHIVE.md"]=""
$payload["components/site/about-page.tsx"]=""
$payload["components/site/contact-page.tsx"]=""
$payload["components/site/home-page.tsx"]=""
$payload["components/site/projects-page.tsx"]=""
$payload["components/site/redesign/archive/archive-footer.tsx"]=""
$payload["components/site/redesign/archive/archive-header.tsx"]=""
$payload["components/site/redesign/archive/archive-home.tsx"]=""
$payload["components/site/redesign/archive/archive-page-renderer.tsx"]=""
$payload["components/site/redesign/archive/archive-ui.tsx"]=""
$payload["components/site/redesign/public-contact-form.tsx"]=""
$payload["components/site/redesign/public-helpers.ts"]=""
$payload["components/site/services-page.tsx"]=""
$payload["components/site/site-footer.tsx"]=""
$payload["components/site/site-header.tsx"]=""
foreach($entry in $payload.GetEnumerator()){$target=Join-Path $root $entry.Key;W $target (D $entry.Value);Write-Host "[FASE 7.5] write  $($entry.Key)" -ForegroundColor DarkGray}
Write-Host "";Write-Host "[FASE 7.5] FIELD ARCHIVE redesign selesai." -ForegroundColor Green;Write-Host "[FASE 7.5] Tidak ada external stock/AI fallback. Media memakai CMS/Firestore dahulu." -ForegroundColor Green;Write-Host "";Write-Host "Validasi:" -ForegroundColor Cyan;Write-Host "  npm run typecheck";Write-Host "  npm run build";Write-Host "  git diff --check";Write-Host "  git status --short"
